  tools.exec_command({"cmd":"gh api repos/jdx/mise/pulls/12823/comments --paginate","workdir":"/Users/jdx/src/mise","yield_time_ms":30000,"max_output_tokens":20000}),
  tools.exec_command({"cmd":"git cat-file -e eb86b9450b6f12adc59983435ca3c7143c4d7bea^{commit} 2>/dev/null; echo $?","workdir":"/Users/jdx/src/mise","yield_time_ms":10000,"max_output_tokens":1000})
]);
